"""Restore the cluster campaign results from the transferred base64 payload.

The production campaign ran on the loong64 cluster (one process per case, 9 way
parallel); only the compact summary (scalars + down-sampled profiles) was
transported back.  This helper rebuilds the per-case JSON files so that
``campaign --assemble`` and the figure generators work unchanged, and verifies
the payload checksum (md5 of the base64 text) before writing anything.
"""

from __future__ import annotations

import base64
import gzip
import hashlib
import json
from pathlib import Path

PARTS = [
    "",
    "",
]

MD5 = "60413c2795366ce914e1fec93dbf1a40"
OUT = Path("artifacts/microbubble_dr_in67_n01/cases")


def main() -> int:
    b64 = "".join(PARTS).strip()
    assert hashlib.md5(b64.encode()).hexdigest() == MD5, "payload checksum mismatch"
    data = json.loads(gzip.decompress(base64.b64decode(b64)).decode())
    OUT.mkdir(parents=True, exist_ok=True)
    for case, blob in data.items():
        run = dict(blob["sc"])
        run["profile"] = blob["pr"]
        (OUT / f"{case}.json").write_text(json.dumps(run))
    print(f"restored {len(data)} cases -> {OUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())